        .Append(mlContext.Transforms.Concatenate("Features",
            "SubjectFeaturized", "DescriptionFeaturized", nameof(TicketData.Priority)))
        .Append(mlContext.Transforms.NormalizeMinMax("Features"))
        .Append(mlContext.MulticlassClassification.Trainers
            .SdcaMaximumEntropy("Label", "Features"))
        .Append(mlContext.Transforms.Conversion.MapKeyToValue("PredictedLabel"));

    Console.WriteLine("Training ticket classification model...");
    var model = pipeline.Fit(split.TrainSet);

    var predictions = model.Transform(split.TestSet);
    var metrics = mlContext.MulticlassClassification.Evaluate(predictions);

    Console.WriteLine("=== Model Evaluation Metrics ===");
    Console.WriteLine($"Macro Accuracy:     {metrics.MacroAccuracy:F4}");
    Console.WriteLine($"Micro Accuracy:     {metrics.MicroAccuracy:F4}");
    Console.WriteLine($"Log Loss:           {metrics.LogLoss:F4}");
    Console.WriteLine($"Log Loss Reduction: {metrics.LogLossReduction:F4}");
    Console.WriteLine("================================");

    mlContext.Model.Save(model, split.TrainSet.Schema, modelPath);
    Console.WriteLine($"Model saved to {modelPath}");
}
